1037:        let task = &req.pending.task;
1038:        self.assert_lock_task(lock, task)?;
1039:        let dir = self.task_dir(task);
1040:        fs::create_dir_all(&dir)?;
1041:
1042:        // ReReadStores: start from the fresh on-disk stores, apply this run's delta.
1043:        let mut sessions = self.read_sessions(task)?.unwrap_or_else(|| SessionsFile {
1044:            task_id: task.as_str().to_string(),
1045:            cwd: req.bootstrap_cwd.clone(),
1046:            codex: LedgerBook {
1047:                tool: req.bootstrap_tool.clone(),
1048:                consults: Vec::new(),
1049:                extra: Map::new(),
1050:            },
1051:            extra: Map::new(),
1052:        });
1053:        sessions
1054:            .add_entry(req.entry)
1055:            .map_err(StoreError::AddEntry)?;
1056:
1057:        let mut findings = self.read_findings(task)?;
1058:        if !req.findings.is_empty() {
1059:            let f = findings.get_or_insert_with(|| FindingsFile {
1060:                task_id: task.as_str().to_string(),
1061:                ..Default::default()
1062:            });
1063:            apply_findings_delta(f, &req.findings)?;
1064:        }
1065:
1066:        // HandoffMarkdown (and any other per-consultation files), each contained.
1067:        for (rel, bytes) in req.files {
1068:            let path = task_slug::contained_join(&dir, rel).map_err(StoreError::Path)?;
1069:            if let Some(parent) = path.parent() {
1070:                fs::create_dir_all(parent)?;
1071:            }
1072:            write_text_atomic(&path, bytes)?;
1073:        }
1074:
1075:        // Findings, then Sessions (the commit point).
1076:        if let Some(f) = &findings {
1077:            write_text_atomic(&dir.join("findings.json"), &f.to_bytes().map_err(map_err)?)?;
1078:        }
1079:        // A pause between findings.json and sessions.json: the ORPHAN window (a kill here leaves
1080:        // the finding written with no ledger entry and the record in `committing`) and the
1081:        // write-lock contention window (this run holds the lock while others wait).
1082:        if req.commit_pause_ms > 0 {
1083:            std::thread::sleep(Duration::from_millis(req.commit_pause_ms));
1084:        }
1085:        write_text_atomic(
1086:            &dir.join("sessions.json"),
1087:            &sessions.to_bytes().map_err(map_err)?,
1088:        )?;
1089:
1090:        // RemoveRecoveryRecord: past the commit point, a cleanup failure is a warning, not
1091:        // an error (F02-5). A launching/survivors record is only removed on Remove (F02-4).
1092:        let mut cleanup_warning = None;
1093:        if req.disposition == RecoveryDisposition::Remove {
1094:            let path = self.pending_path(req.pending);
1095:            if let Err(e) = fs::remove_file(&path) {
1096:                if e.kind() != io::ErrorKind::NotFound {
1097:                    cleanup_warning = Some(format!(
1098:                        "sessions.json committed, but the recovery record {} could not be removed: {e}",
1099:                        path.display()
1100:                    ));
1101:                }
1102:            }
1103:        }
1104:
1105:        Ok(CommitReceipt {
1106:            committed: true,
1107:            cleanup_warning,
1108:            wait_ms: lock.wait_ms(),
1109:        })
1110:    }
